let lang='zh';const t=k=>words[k]?.[lang==='zh'?0:1]??k;const l=x=>Array.isArray(x)?x[lang==='zh'?0:1]:x;const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const txt=(key,values={})=>Object.entries(values).reduce((s,[k,v])=>s.replaceAll('{'+k+'}',v),t(key));
const state={scene:'tasks',hardware:'notch',mode:'closed',tab:'needs',active:'login',mainActive:'login',workTab:'decision',camera:null,returnContext:null,videoPaused:matchMedia('(prefers-reduced-motion: reduce)').matches,newDraft:'',eventAdded:false};
const contexts=new Map();const ctx=id=>{if(!contexts.has(id))contexts.set(id,{draft:'',messages:[],scroll:{},mainScroll:null});return contexts.get(id)};
const workBy=id=>work.find(w=>w.id===id),agentFor=id=>agents.find(a=>a.id===workBy(id)?.owner),pending=()=>decisions.filter(d=>d.status==='open');
const avatar=a=>`<span class="avatar" style="--agent:${a.color}">${esc(a.initial)}</span>`;
const badge=w=>`<span class="badge ${w.stage}"><i class="dot"></i>${t(w.stage)}</span>`;
const steps=w=>`<span class="step-track">${w.plan.map((_,i)=>`<i class="${i<meta[w.id].completed?'done':''}"></i>`).join('')}</span>`;
const el=id=>document.getElementById(id);let drag=null,toastTimer,newWorkCount=0;
function fitCamera(){const minX=Math.min(...agents.map(a=>a.x)),minY=Math.min(...agents.map(a=>a.y)),maxX=Math.max(...agents.map(a=>a.x+360)),maxY=Math.max(...agents.map(a=>a.y+246)),w=innerWidth,h=innerHeight-112,top=80,bottom=innerWidth<=800?155:105;const z=Math.max(.16,Math.min(1,(w-100)/(maxX-minX),(h-top-bottom)/(maxY-minY)));return{x:(w-(maxX-minX)*z)/2-minX*z,y:top+(h-top-bottom-(maxY-minY)*z)/2-minY*z,z,auto:true}}
function syncCanvas(){const c=state.camera;el('world').style.transform=`translate(${c.x}px,${c.y}px) scale(${c.z})`;document.querySelectorAll('[data-node]').forEach(node=>{const a=agents.find(a=>a.id===node.dataset.node);node.style.left=a.x+'px';node.style.top=a.y+'px';node.classList.toggle('selected',state.returnContext&&node.dataset.work===state.active)});const label=document.querySelector('.zoom-label');if(label)label.textContent=Math.round(c.z*100)+'%'}
function nodeHTML(a){const w=work.find(w=>w.owner===a.id);return `<article class="node" data-node="${a.id}" data-work="${w.id}" data-human="${a.control==='human'}" style="left:${a.x}px;top:${a.y}px"><header class="node-header" data-drag-node="${a.id}"><span class="row">${avatar(a)}<strong>${a.name}</strong><span class="model">${a.model}</span></span><button class="icon-button" data-locate="${w.id}" aria-label="${t('locate')} ${a.name}" title="${t('locate')}">${icon('target')}</button></header><div class="node-topic"><h2>${esc(l(w.title))}</h2>${a.control==='human'?`<span class="badge attention">${t('human')}</span>`:badge(w)}</div><div class="node-terminal"><span class="${pending().some(d=>d.id===w.id)?'needs':'latest'}">❯ ${esc(l(w.last))}</span>\n\n${w.plan.slice(0,2).map((p,i)=>(i<meta[w.id].completed?'✓ ':'· ')+esc(l(p))).join('\n')}</div><footer class="node-footer"><span class="progress">${steps(w)}${meta[w.id].completed}/${w.plan.length}</span><div class="row" style="gap:2px"><button class="button" data-control="${a.id}">${t(a.control==='human'?'release':'take')}</button><button class="button" data-discuss="${w.id}">${icon('island')}${t('chatTab')}</button></div></footer></article>`}
function triggerHTML(){const back=!!state.returnContext;return `<span class="left-wing"><span class="n-orb">n</span><span>${back?agentFor(state.active).name:txt('track',{n:work.length})}</span></span><span class="notch-slot" aria-hidden="true"><i class="camera-dot"></i></span><span class="right-wing">${back?`<span>${t('returnDecision')}</span>${icon('back')}`:`<b class="waiting-count" data-testid="pending-count">${pending().length}</b><span>${t(pending().length?'needYou':'allClear')}</span>${icon('chevron')}`}</span>`}
function overviewHTML(){const rows=state.tab==='needs'?work.filter(w=>pending().some(d=>d.id===w.id)):work;return `<header class="panel-heading"><div class="between"><div class="row" style="gap:12px"><span class="n-orb head-orb">n</span><div><div class="eyebrow">NORMA ISLAND</div><h2>${pending().length?txt('needTitle',{n:pending().length}):t('quietTitle')}</h2></div></div><button class="icon-button" data-action="close" aria-label="${t('closeIsland')}">${icon('close')}</button></div><p class="subtitle">${t('islandSubtitle')}</p></header><nav class="panel-tabs" aria-label="${t('all')}">${['needs','all','deliveries'].map(tab=>`<button data-tab="${tab}" role="tab" aria-selected="${state.tab===tab}">${t(tab)}<span class="count">${tab==='needs'?pending().length:tab==='all'?work.length:1}</span></button>`).join('')}</nav><div class="panel-scroll">${state.tab==='deliveries'?artifactHTML():`${state.tab==='needs'&&pending().some(d=>d.id==='login')?`<p class="queue-intro">${icon('spark')}${t('firstHint')}</p>`:''}${rows.length?rows.map(w=>{const a=agentFor(w.id);return `<button class="work-row" data-open-work="${w.id}">${avatar(a)}<span class="work-info"><h3>${esc(l(w.title))}</h3><p>${a.name} · ${a.model}</p>${state.tab==='all'?`<span class="status-line">${steps(w)}${meta[w.id].completed}/${w.plan.length}</span>`:''}</span><span class="row-end">${badge(w)}${icon('right')}</span></button>`}).join(''):`<div class="panel-empty">${icon('check')}${t('noneHint')}</div>`}`}</div><footer class="panel-footer"><span>${t('quietRecord')}</span><button data-action="global">${icon('message')}${t('askNorma')}</button></footer>`}
function artifactHTML(){return `<article class="artifact"><div class="file-icon">${icon('file')}</div><div><h3>${t('artifactTitle')}</h3><p>${t('artifactMeta')}</p><button class="button" data-action="artifact">${t('viewArtifact')}${icon('arrow')}</button></div></article>`}
function messageHTML(m){const user=m.role==='user';return `<article class="chat-message">${user?`<span class="user-avatar">${t('you')}</span>`:'<span class="n-orb">n</span>'}<div><header><span>${user?t('you'):'Norma'}</span><small>${m.citation?esc(m.citation)+' · ':''}${m.time||t('now')}</small></header><p>${esc(l(m.text))}</p></div></article>`}
function decisionHTML(id,place='island'){const w=workBy(id),a=agentFor(id),d=pending().find(d=>d.id===id);if(!d)return `<div class="receipt"><div class="row">${icon('check')}${t(w.stage==='merge'?'reviewTitle':w.stage==='working'?'receiptTitle':'noDecision')}</div><p>${t(w.stage==='merge'?'reviewText':w.stage==='working'?'receiptText':'routineHint')}</p></div>${place==='island'&&pending().length?`<button class="next-decision" data-action="next">${t('next')}${icon('right')}</button>`:''}`;return `${a.control==='human'?`<p class="human-hint">${t('humanHint')}</p>`:''}<div class="request-heading"><span class="n-orb">n</span><span>${t('normaSays')}</span></div><h3 class="request-question">${esc(l(d.title))}</h3><div class="recommendation"><div class="recommendation-label">${icon('spark')}${t('recommended')} · ${a.name}</div><p>${esc(l(d.recommended))}</p><small>${esc(l(d.reason))}</small></div>${id==='login'?`<p class="impact-line">${icon('link')}${t('impact')}</p>`:''}<div class="decision-actions"><button class="button primary" data-apply="${id}" data-testid="${place==='island'?'apply-decision':'main-apply'}" ${a.control==='human'?'disabled':''}>${icon('check')}${t(d.kind==='review'?'accept':d.kind==='permission'?'allow':'adopt')}</button><button class="button" data-edit="${id}" ${place==='island'?'data-action="edit"':''} ${a.control==='human'?'disabled':''}>${t('edit')}</button><button class="button quiet" data-evidence="${id}">${t('source')}</button></div>`}
function composerHTML(id,place='island'){const global=id==='norma';return `<div class="context-composer"><form class="composer-box" data-form="chat" data-work-id="${id}" data-place="${place}"><textarea name="message" data-draft-work="${id}" data-testid="${place==='main'?'main-composer':'composer'}" aria-label="${t(global?'globalPlaceholder':'workPlaceholder')}" placeholder="${t(global?'globalPlaceholder':'workPlaceholder')}">${esc(ctx(id).draft)}</textarea><div class="composer-bottom"><span class="composer-scope">${icon('layers')}<span>${global?t('globalScope'):t('scope')+'：'+esc(l(meta[id].short))}</span></span><button class="send-button" type="submit" data-testid="${place==='main'?'main-send':'send'}" aria-label="${t('send')}">${icon('send')}</button></div></form><div class="composer-note"><span>${t('inputHint')}</span><span>${t('demo')}</span></div></div>`}
function workHTML(){const id=state.active,w=workBy(id),a=agentFor(id);return `<header class="work-heading"><div class="between"><button class="work-back" data-action="overview">${icon('left')}${t('back')}</button><div class="row" style="gap:3px"><button class="icon-button" data-action="locate" aria-label="${t('locate')}" title="${t('locate')}">${icon('target')}</button><button class="icon-button" data-action="close" aria-label="${t('closeIsland')}">${icon('close')}</button></div></div><div class="between"><h2 data-testid="active-work">${esc(l(w.title))}</h2><span data-testid="work-stage">${badge(w)}</span></div><div class="work-owner">${avatar(a)}<span>${a.name} · ${a.model}</span><span>·</span><span>${t('independent')}</span></div></header><nav class="work-nav"><div class="row">${['decision','chat','progress'].map(tab=>`<button data-work-tab="${tab}" aria-selected="${state.workTab===tab}">${t(tab+'Tab')}</button>`).join('')}</div><span class="row step-counter">${steps(w)}${txt('steps',{n:meta[id].completed,total:w.plan.length})}</span></nav><div class="work-body" data-scroll-work="${id}" data-scroll-tab="${state.workTab}">${state.workTab==='decision'?decisionHTML(id):state.workTab==='chat'?[...(seedMessages[id]||[]),...ctx(id).messages].map(messageHTML).join(''):w.plan.map((p,i)=>`<div class="plan-item ${i<meta[id].completed?'complete':''}"><i>${i<meta[id].completed?'✓':i+1}</i><span>${esc(l(p))}</span></div>`).join('')+`<p class="latest-progress">${t('lastProgress')}：${esc(l(w.last))}</p>`}</div>${composerHTML(id)}`}
function globalHTML(){return `<header class="panel-heading"><div class="between"><div><div class="eyebrow">${t('globalScope')}</div><h2>${t('globalTitle')}</h2></div><div class="row"><button class="icon-button" data-action="overview" aria-label="${t('all')}">${icon('list')}</button><button class="icon-button" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div></div></header><div class="work-body" data-scroll-work="norma" data-scroll-tab="chat">${messageHTML({role:'assistant',text:txt('globalIntro',{n:work.length,pending:pending().length})})}${ctx('norma').messages.map(messageHTML).join('')}</div>${composerHTML('norma')}`}
function briefHTML(){return `<header class="panel-heading"><div class="between"><div><div class="eyebrow">WELCOME BACK</div><h2>${t('briefTitle')}</h2></div><button class="icon-button" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div><p class="subtitle">${t('briefSubtitle')}</p></header><div class="panel-scroll brief-body"><div class="brief-item">${icon('alert')}<div><strong>${txt('briefNeeds',{n:pending().length})}</strong><p>${t('briefNeedsText')}</p></div></div><div class="brief-item">${icon('file')}<div><strong>${t('briefDelivery')}</strong><p>${t('briefDeliveryText')}</p></div></div><div class="brief-item">${icon('clock')}<div><strong>${t('briefWork')}</strong><p>${t('briefWorkText')}</p></div></div></div><footer class="panel-footer"><span>${t('demo')}</span><button data-action="overview">${t('handleNeeds')}${icon('right')}</button></footer>`}
function taskRow(w){const a=agentFor(w.id);return `<button class="task-list-row" data-main-work="${w.id}" aria-selected="${state.mainActive===w.id}"><span class="status-symbol ${w.stage}">${icon(['done','merge'].includes(w.stage)?'check':['attention','approval','ready'].includes(w.stage)?'alert':'ring')}</span><span class="list-title">${esc(l(w.title))}</span><span class="list-status">${t(w.stage)}</span>${avatar(a)}</button>`}
function mainThreadHTML(){const id=state.mainActive;if(!id)return `<div class="main-thread-empty"><span class="n-orb">n</span>${t('mainEmpty')}</div>`;const w=workBy(id),a=agentFor(id);return `<header class="main-thread-heading"><div class="row"><button class="icon-button mobile-back" data-action="close-main" aria-label="${t('all')}">${icon('left')}</button><div><h2 data-testid="main-title">${esc(l(w.title))}</h2><div class="thread-meta"><span>${a.name}</span><span>·</span><span>${t(w.stage)}</span></div></div></div><div class="row" style="gap:2px"><button class="icon-button" data-locate="${id}" aria-label="${t('locate')}" title="${t('locate')}">${icon('target')}</button><button class="icon-button" data-action="main-to-island" aria-label="${t('mainToIsland')}" title="${t('mainToIsland')}">${icon('island')}</button><button class="icon-button" data-action="close-main" aria-label="${t('close')}">${icon('close')}</button></div></header><div class="main-thread-content" data-main-scroll="${id}">${[...(seedMessages[id]||[]),...ctx(id).messages].map(messageHTML).join('')}${pending().some(d=>d.id===id)?`<section class="main-decision">${decisionHTML(id,'main')}</section>`:''}</div>${composerHTML(id,'main')}`}
function tasksHTML(){const groups=[['needs',work.filter(w=>pending().some(d=>d.id===w.id))],['processing',work.filter(w=>['running','working','queued'].includes(w.stage))],['waitingGroup',work.filter(w=>w.stage==='waiting')],['doneGroup',work.filter(w=>['done','merge'].includes(w.stage))]];return `<nav class="task-rail" aria-label="Norma"><button data-action="global" aria-label="${t('askNorma')}" title="${t('askNorma')}">${icon('spark')}</button><button data-scene="canvas" aria-label="${t('canvas')}" title="${t('canvas')}">${icon('grid')}</button><button class="active" data-action="show-task-list" aria-label="${t('all')}" title="${t('all')}">${icon('list')}</button><div class="rail-bottom"><button data-action="toggle-island" aria-label="${t('openIsland')}"><span class="n-orb">n</span></button><button data-action="help" aria-label="${t('help')}" title="${t('help')}">${icon('bulb')}</button></div></nav><section class="task-main"><form class="new-task-box" data-form="create"><textarea data-testid="new-task" name="goal" placeholder="${t('newTask')}" aria-label="${t('newTask')}">${esc(state.newDraft)}</textarea><div class="new-task-bottom"><span class="row"><span class="n-orb">n</span>${t('coordinator')}</span><button class="send-button" data-testid="create-task" type="submit" aria-label="${t('create')}">${icon('send')}</button></div></form><p class="main-brief"><span class="n-orb">n</span>${t('mainBrief')}</p>${groups.filter(([,rows])=>rows.length).map(([name,rows])=>`<section class="task-group"><h2>${t(name)}<span>${rows.length}</span></h2>${rows.map(taskRow).join('')}</section>`).join('')}<p class="main-footer-note">${t('mainFoot')}</p></section><section class="main-thread">${mainThreadHTML()}</section>`}
function otherHTML(){return `<header class="other-titlebar"><span class="traffic-lights"><i></i><i></i><i></i></span><span>${t('notesApp')}</span><button data-scene="tasks">${t('backCanvas')}</button></header><div class="note-paper"><div class="note-date">${t('noteDate')}</div><h2>${t('noteTitle')}</h2><p>${t('noteText')}</p>${[1,2,3].map(i=>`<div class="note-check ${i===1?'complete':''}"><i></i>${t('note'+i)}</div>`).join('')}<div class="note-foot">${t('noteFoot')}</div></div>`}
function toolbarHTML(){return `<div class="demo-controls"><label>${t('previewControls')}</label>${['tasks','canvas','desktop'].map(scene=>`<button data-scene="${scene}" aria-pressed="${state.scene===scene}">${icon(scene==='tasks'?'list':scene==='canvas'?'grid':'window')}${t(scene)}</button>`).join('')}<span class="divider"></span><button data-action="event">${icon('plus')}${t('event')}</button><button data-action="brief">${icon('clock')}${t('brief')}</button></div><div class="display-controls"><select data-testid="hardware" aria-label="${t('notch')}"><option value="notch" ${state.hardware==='notch'?'selected':''}>${t('notch')}</option><option value="flat" ${state.hardware==='flat'?'selected':''}>${t('flat')}</option></select><span class="divider"></span><button class="icon-button" data-zoom="-1" aria-label="${t('zoomOut')}">${icon('minus')}</button><span class="zoom-label">${Math.round(state.camera.z*100)}%</span><button class="icon-button" data-zoom="1" aria-label="${t('zoomIn')}">${icon('plus')}</button><button class="icon-button" data-action="fit" aria-label="${t('fit')}">${icon('grid')}</button></div><span class="prototype-label">${t('demo')}</span>`}
function remember(){document.querySelectorAll('[data-draft-work]').forEach(input=>{if(input.closest('[inert]')||!input.getClientRects().length)return;if(input===document.activeElement||!document.querySelector(`[data-draft-work="${input.dataset.draftWork}"]:focus`))ctx(input.dataset.draftWork).draft=input.value});document.querySelectorAll('[data-scroll-work]').forEach(s=>ctx(s.dataset.scrollWork).scroll[s.dataset.scrollTab]=s.scrollTop);document.querySelectorAll('[data-main-scroll]').forEach(s=>ctx(s.dataset.mainScroll).mainScroll=s.scrollTop)}
function restore(){document.querySelectorAll('[data-scroll-work]').forEach(s=>{const v=ctx(s.dataset.scrollWork).scroll[s.dataset.scrollTab];s.scrollTop=v==='end'?s.scrollHeight:v||0});document.querySelectorAll('[data-main-scroll]').forEach(s=>{const v=ctx(s.dataset.mainScroll).mainScroll;s.scrollTop=v===null||v==='end'?s.scrollHeight:v})}
function render(){
 const focused=document.activeElement?.dataset.draftWork,selection=focused?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null;
 document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.body.dataset.scene=state.scene;document.body.dataset.hardware=state.hardware;
 el('menubar').innerHTML=`<span class="row"><span class="traffic-lights"><i></i><i></i><i></i></span><span class="n-orb" style="width:21px;height:21px;font-size:14px">n</span><strong class="menu-app">${state.scene==='desktop'?t('notesApp'):'Local'}</strong><span class="optional-menu">${t('fileMenu')}</span><span class="optional-menu">${t('editMenu')}</span><span>${state.scene==='tasks'?t('tasks'):t('viewMenu')}</span></span><span class="row menu-right">${icon('wifi')}${icon('battery')}<time>${new Date().toLocaleTimeString(lang==='zh'?'zh-CN':'en-US',{hour:'2-digit',minute:'2-digit'})}</time></span>`;
 el('app-hud').innerHTML=`<div class="project-heading"><span class="project-symbol">${icon(state.scene==='tasks'?'list':'grid')}</span><div><h1>Norma OS <span style="opacity:.35;margin:0 7px">/</span> ${t('project')}</h1><p>${t('projectSub')}</p></div></div><div class="hud-actions"><button class="icon-button" data-action="video" aria-label="${t(state.videoPaused?'videoPlay':'videoPause')}" title="${t(state.videoPaused?'videoPlay':'videoPause')}">${icon(state.videoPaused?'play':'pause')}</button><button class="icon-button lang" data-action="language" aria-label="${t('language')}">${lang==='zh'?'EN':'中'}</button><button class="icon-button" data-action="help" aria-label="${t('help')}" title="${t('help')}">${icon('bulb')}</button></div>`;
 el('world').innerHTML=`<div class="canvas-label"><i class="dot"></i>Norma OS <span style="opacity:.4">/</span>${t('project')}</div>${agents.map(nodeHTML).join('')}`;
 el('task-workspace').className='task-workspace '+(state.mainActive?'has-thread':'no-thread');el('task-workspace').innerHTML=tasksHTML();el('other-app').innerHTML=otherHTML();el('demo-toolbar').innerHTML=toolbarHTML();
 const open=state.mode!=='closed';el('island').dataset.open=String(open);const trigger=el('island').querySelector('.island-trigger');trigger.innerHTML=triggerHTML();trigger.setAttribute('aria-expanded',String(open));trigger.setAttribute('aria-label',t(state.returnContext?'returnDecision':open?'closeIsland':'openIsland'));
 const panel=el('island-panel');panel.inert=!open;if(open)panel.innerHTML=state.mode==='overview'?overviewHTML():state.mode==='work'?workHTML():state.mode==='global'?globalHTML():briefHTML();
 el('canvas-return').innerHTML=state.returnContext&&state.scene==='canvas'?`<span>${icon('target')}${agentFor(state.active).name} · ${t('viewing')}<span style="opacity:.5">/</span>${t('returnDecision')} ↑</span>`:'';
 syncCanvas();restore();
 if(focused){const inputs=[...document.querySelectorAll(`[data-draft-work="${focused}"]`)];const input=inputs.find(i=>i.getClientRects().length&&!i.closest('[inert]'));if(input){input.focus({preventScroll:true});input.setSelectionRange(...selection)}}
}
function notice(text){el('toast').textContent=text;el('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').classList.remove('show'),3600)}
function openWork(id){if(!workBy(id))return;state.active=id;state.workTab='decision';state.mode='work';state.returnContext=null;render()}
function closeIsland(){state.mode='closed';render();el('island').querySelector('.island-trigger').focus({preventScroll:true})}
function locateWork(id,fromMain=false){const a=agentFor(id);if(!a)return;state.returnContext={scene:state.scene,camera:{...state.camera},mode:fromMain?'closed':state.mode,active:id,workTab:state.workTab,mainActive:state.mainActive,fromMain};state.active=id;state.scene='canvas';state.mode='closed';const z=innerWidth>800?1.25:Math.min(1.1,(innerWidth-48)/360);state.camera={x:innerWidth/2-(a.x+180)*z,y:(innerHeight-112)/2-(a.y+123)*z,z,auto:false};render()}
function returnToWork(){const prior=state.returnContext;if(!prior)return;state.scene=prior.scene;state.camera={...prior.camera};state.active=prior.active;state.workTab=prior.workTab;state.mainActive=prior.fromMain?prior.active:prior.mainActive;state.mode=prior.mode==='closed'&&!prior.fromMain?'work':prior.mode;state.returnContext=null;render()}
function applyDecision(id,answer,version){const d=decisions.find(d=>d.id===id),a=agentFor(id);if(!d||d.status!=='open'){notice(t('alreadyHandled'));return false}if(version!==undefined&&version!==d.version){notice(t('outdated'));return false}if(a.control==='human'){notice(t('humanHint'));return false}const w=workBy(id),c=ctx(id);d.status='resolved';d.version++;w.stage=d.kind==='review'?'merge':'working';w.last=d.kind==='review'?['本轮验收通过，等待合并安排','Revision accepted; awaiting merge arrangements']:['用户已确认方案，原 Agent 继续执行','User confirmed the approach; the original agent can continue'];c.messages.push({role:'user',text:answer||d.recommended},{role:'assistant',citation:a.name,text:d.kind==='review'?words.reviewText:words.confirmed});c.scroll.chat='end';c.mainScroll='end';render();notice(t('confirmed'));return true}
function showDialog(content){el('detail-dialog').innerHTML=content;const title=el('detail-dialog').querySelector('h2');if(title){title.id='detail-title';el('detail-dialog').setAttribute('aria-labelledby','detail-title')}if(!el('detail-dialog').open)el('detail-dialog').showModal()}
function editDecision(id){const d=pending().find(d=>d.id===id);if(!d)return;showDialog(`<form data-form="edit" data-work-id="${id}" data-version="${d.version}"><div class="between"><h2>${t('editTitle')}</h2><button type="button" class="icon-button" data-action="close-dialog" aria-label="${t('close')}">${icon('close')}</button></div><p>${esc(l(d.title))}</p><label for="edit-answer">${t('yourAnswer')}</label><textarea id="edit-answer" data-testid="decision-edit" name="answer" required>${esc(l(d.recommended))}</textarea><footer><button type="button" class="button quiet" data-action="close-dialog">${t('cancel')}</button><button class="button primary" type="submit" data-testid="submit-edit">${t('submitEdit')}</button></footer></form>`)}
function evidence(id){const d=decisions.find(d=>d.id===id);if(!d)return;showDialog(`<div class="between"><h2>${t('evidenceTitle')}</h2><button class="icon-button" data-action="close-dialog" aria-label="${t('close')}">${icon('close')}</button></div><p>${t('evidenceSample')}</p>${[['original',d.title],['basis',d.evidence],['impactLabel',d.impact]].map(([key,text])=>`<label>${t(key)}</label><p>${esc(l(text))}</p>`).join('')}<footer><button class="button" data-action="close-dialog">${t('close')}</button></footer>`)}
function artifactText(){return lang==='zh'?'# Norma 工作台视觉规范（原型示例）\n\n- 主题：深色中性底色，清晰的内容层级。\n- 间距：相关内容靠近，工作之间有明确分组。\n- 状态：hover、pressed、focus、selected、disabled 均可辨认。\n- 减少动态效果：背景视频暂停，交互即时更新。\n\n这是示例交付物，不是正式 App 的验收记录。':'# Norma workbench visual conventions (prototype sample)\n\n- Theme: dark neutral surfaces with clear hierarchy.\n- Spacing: group related content and separate work items.\n- States: hover, pressed, focus, selected and disabled are visible.\n- Reduced motion: pause wallpaper and update UI immediately.\n\nThis sample is not an actual app acceptance record.'}
function showArtifact(){showDialog(`<div class="between"><h2>${t('artifactTitle')}</h2><button class="icon-button" data-action="close-dialog" aria-label="${t('close')}">${icon('close')}</button></div><p>${t('artifactNote')}</p><pre>${esc(artifactText())}</pre><footer><button class="button primary" data-action="download">${icon('download')}${t('download')}</button></footer>`)}
function downloadArtifact(){const url=URL.createObjectURL(new Blob([artifactText()],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='norma-visual-spec-example.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function sendChat(form){const id=form.dataset.workId,text=form.elements.message.value.trim();if(!text){notice(t('emptyMessage'));return}const c=ctx(id);c.messages.push({role:'user',text},{role:'assistant',text:words[id==='norma'?'globalReply':'normalReply']});c.draft='';c.scroll.chat='end';c.mainScroll='end';if(form.dataset.place==='island')state.workTab='chat';render();document.querySelector(`[data-testid="${form.dataset.place==='main'?'main-composer':'composer'}"]`)?.focus({preventScroll:true})}
function createTask(form){const text=form.elements.goal.value.trim();if(!text){notice(t('emptyMessage'));return}const id='new-'+(++newWorkCount),owner='coordinator-'+newWorkCount;agents.push({id:owner,name:'Norma',initial:'n',color:'#b3d7c0',model:'Coordinator',x:1535,y:180+(newWorkCount-1)*290,control:'agent'});work.push({id,owner,title:[text,text],stage:'queued',last:['已记录目标，等待拆解执行方案','Goal recorded; awaiting an execution plan'],plan:[['明确目标与约束','Clarify the goal and constraints'],['整理执行方案','Prepare an execution plan'],['派给合适的 Agent','Assign to the right agent']]});meta[id]={completed:0,short:[text,text]};seedMessages[id]=[{role:'user',text},{role:'assistant',text:words.createReceipt}];state.newDraft='';state.mainActive=id;state.scene='tasks';render()}
function simulateEvent(){if(state.eventAdded){notice(t('eventRepeated'));return}state.eventAdded=true;workBy('regression').stage='attention';workBy('regression').last=['英文布局有一处溢出，等待确认修复范围','One English layout overflow needs a scope decision'];decisions.push({id:'regression',kind:'question',title:['英文长标题溢出，需要先补齐再验收吗？','Should the English title overflow be fixed before review?'],recommended:['先修复英文溢出，再继续本轮回归','Fix the English overflow, then continue regression'],reason:['保持双语体验一致，只调整受影响的布局。','Keep locales consistent and adjust only the affected layout.'],evidence:['Nova 在英文窄窗口下发现一处标题溢出。','Nova found a title overflow in a narrow English window.'],impact:['只影响本轮工作台的英文布局。','Only this iteration’s English workbench layout.'],status:'open',version:1});render();notice(t('eventNotice'))}
function zoom(factor,px=innerWidth/2,py=(innerHeight-112)/2){const c=state.camera,z=Math.min(2,Math.max(.16,c.z*factor)),r=z/c.z;c.x=px-(px-c.x)*r;c.y=py-(py-c.y)*r;c.z=z;c.auto=false;syncCanvas()}
function markKeyboard(e){document.body.classList.toggle('keyboard-action',e instanceof KeyboardEvent||e.detail===0)}
document.addEventListener('input',e=>{const id=e.target.dataset.draftWork;if(id){ctx(id).draft=e.target.value;document.querySelectorAll(`[data-draft-work="${id}"]`).forEach(input=>{if(input!==e.target)input.value=e.target.value})}else if(e.target.matches('[data-testid="new-task"]'))state.newDraft=e.target.value});
document.addEventListener('scroll',e=>{if(e.target.dataset?.scrollWork)ctx(e.target.dataset.scrollWork).scroll[e.target.dataset.scrollTab]=e.target.scrollTop;if(e.target.dataset?.mainScroll)ctx(e.target.dataset.mainScroll).mainScroll=e.target.scrollTop},true);
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();remember();if(form.dataset.form==='chat')sendChat(form);else if(form.dataset.form==='create')createTask(form);else if(form.dataset.form==='edit'){const text=form.elements.answer.value.trim();if(text&&applyDecision(form.dataset.workId,text,Number(form.dataset.version)))el('detail-dialog').close()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-testid="hardware"]')){remember();state.hardware=e.target.value;render()}});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;markKeyboard(e);remember();
 if(b.dataset.scene){state.scene=b.dataset.scene;render();return}
 if(b.dataset.mainWork){state.mainActive=b.dataset.mainWork;render();return}
 if(b.dataset.openWork||b.dataset.discuss){openWork(b.dataset.openWork||b.dataset.discuss);return}
 if(b.dataset.locate){locateWork(b.dataset.locate,!!b.closest('.main-thread'));return}
 if(b.dataset.apply){applyDecision(b.dataset.apply);return}
 if(b.dataset.edit){editDecision(b.dataset.edit);return}
 if(b.dataset.evidence){evidence(b.dataset.evidence);return}
 if(b.dataset.tab){state.tab=b.dataset.tab;render();return}
 if(b.dataset.workTab){state.workTab=b.dataset.workTab;render();return}
 if(b.dataset.control){const a=agents.find(a=>a.id===b.dataset.control);a.control=a.control==='human'?'agent':'human';render();notice(t(a.control==='human'?'takeNotice':'releaseNotice'));return}
 if(b.dataset.zoom){zoom(Number(b.dataset.zoom)>0?1.16:1/1.16);return}
 switch(b.dataset.action){
 case 'toggle-island':if(state.returnContext)returnToWork();else if(state.mode==='closed'){state.mode='overview';render()}else closeIsland();break;
 case 'close':closeIsland();break;
 case 'overview':state.mode='overview';state.tab='needs';render();break;
 case 'next':if(pending().length)openWork(pending()[0].id);break;
 case 'global':state.mode='global';state.returnContext=null;render();break;
 case 'locate':locateWork(state.active);break;
 case 'brief':state.mode='brief';state.returnContext=null;render();break;
 case 'event':simulateEvent();break;
 case 'artifact':showArtifact();break;
 case 'download':downloadArtifact();break;
 case 'close-dialog':el('detail-dialog').close();break;
 case 'main-to-island':openWork(state.mainActive);break;
 case 'close-main':state.mainActive=null;render();break;
 case 'show-task-list':state.mainActive=null;state.scene='tasks';render();break;
 case 'fit':state.scene='canvas';state.camera=fitCamera();state.returnContext=null;render();break;
 case 'language':lang=lang==='zh'?'en':'zh';render();break;
 case 'video':state.videoPaused=!state.videoPaused;if(state.videoPaused)el('wallpaper').pause();else el('wallpaper').play().catch(()=>{state.videoPaused=true;render()});render();break;
 case 'help':showDialog(`<div class="between"><h2>${t('helpTitle')}</h2><button class="icon-button" data-action="close-dialog" aria-label="${t('close')}">${icon('close')}</button></div><p>${t('helpText')}</p><p>${t('helpMotion')}</p><p>${t('helpLimits')}</p><footer><button class="button" data-action="close-dialog">${t('close')}</button></footer>`);break;
 }
});
document.addEventListener('keydown',e=>{if(el('detail-dialog').open)return;markKeyboard(e);if(e.key==='Escape'){e.preventDefault();remember();if(state.returnContext)returnToWork();else if(state.mode!=='closed')closeIsland();return}if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&e.target.matches('textarea[data-draft-work],textarea[data-testid="new-task"]')){e.preventDefault();e.target.form.requestSubmit()}});
document.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button')||state.scene!=='canvas')return;const viewport=e.target.closest('.canvas-viewport');if(!viewport)return;const header=e.target.closest('[data-drag-node]');if(e.target.closest('.node')&&!header)return;const a=header?agents.find(a=>a.id===header.dataset.dragNode):null,c=state.camera;drag={id:e.pointerId,a,viewport,x:e.clientX,y:e.clientY,startX:a?a.x:c.x,startY:a?a.y:c.y};viewport.setPointerCapture(e.pointerId);viewport.classList.add('panning');e.preventDefault()});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.a){drag.a.x=drag.startX+dx/state.camera.z;drag.a.y=drag.startY+dy/state.camera.z}else{state.camera.x=drag.startX+dx;state.camera.y=drag.startY+dy;state.camera.auto=false}syncCanvas()});
function endDrag(){if(drag)drag.viewport.classList.remove('panning');drag=null}document.addEventListener('pointerup',endDrag);document.addEventListener('pointercancel',endDrag);
document.addEventListener('wheel',e=>{if(!e.target.closest('.canvas-viewport')||state.scene!=='canvas')return;e.preventDefault();if(e.ctrlKey||e.metaKey)zoom(Math.exp(-e.deltaY*.002),e.clientX,e.clientY-112);else{state.camera.x-=e.deltaX;state.camera.y-=e.deltaY;state.camera.auto=false;syncCanvas()}},{passive:false});
window.addEventListener('resize',()=>{if(state.camera.auto)state.camera=fitCamera();syncCanvas()});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');reduced.addEventListener('change',e=>{if(e.matches){state.videoPaused=true;el('wallpaper').pause();remember();render()}});
state.camera=fitCamera();if(state.videoPaused)el('wallpaper').pause();render();
